鉴于甲方是相关数字内容的合法权利人，乙方是专业的市场推广公司，双方本着平等互利的原则，就甲方授权乙方在特定区域内使用特定数字内容进行市场推广事宜，达成如下协议，以资共同遵守。', '正文章节': [{'章节编号': '第一条', '章节标题': '定义与解释', '条款列表': [{'条款编号': '1.1', '条款大致说明': '定义核心术语，包括但不限于：授权内容、授权区域、授权期限、推广效果、分成收入、保密信息等。', '子条款列表': [], 'locator': '1.1'}], 'locator': '1'}, {'章节编号': '第二条', '章节标题': '授权内容与范围', '条款列表': [{'条款编号': '2.1', '条款大致说明': '授权内容界定：明确授权素材的具体清单（如手游角色形象、宣传视频、游戏截图等），并约定以附件形式列明。', '子条款列表': [], 'locator': '2.1'}, {'条款编号': '2.2', '条款大致说明': '授权性质：明确为普通使用许可，非独占、不可转让、不可转授权。', '子条款列表': [], 'locator': '2.2'}, {'条款编号': '2.3', '条款大致说明': '授权区域：明确授权使用的地理范围仅限于中华人民共和国江苏省行政区域内。', '子条款列表': [], 'locator': '2.3'}, {'条款编号': '2.4', '条款大致说明': '授权期限：明确授权起始日期与终止日期，总期限约为一年。', '子条款列表': [], 'locator': '2.4'}, {'条款编号': '2.5', '条款大致说明': '使用目的与方式：明确授权内容仅可用于双方约定的市场推广活动，并约定具体的使用渠道（如线上广告、社交媒体、线下活动等）及形式要求。', '子条款列表': [], 'locator': '2.5'}, {'条款编号': '2.6', '条款大致说明': '使用限制：明确禁止性行为，包括但不限于：修改授权内容核心要素、用于授权范围之外的用途、将授权内容用于任何违法或不道德的宣传、转授权给任何第三方等。', '子条款列表': [], 'locator': '2.6'}], 'locator': '2'}, {'章节编号': '第三条', '章节标题': '费用与结算', '条款列表': [{'条款编号': '3.1', '条款大致说明': '合作模式：明确本协议采用按推广效果分成的合作模式。', '子条款列表': [], 'locator': '3.1'}, {'条款编号': '3.2', '条款大致说明': '分成基数与比例：约定分成收入的计算基数（如基于推广带来的新增用户充值额、有效注册用户数等关键指标），以及甲乙双方的具体分成比例。', '子条款列表': [], 'locator': '3.2'}, {'条款编号': '3.3', '条款大致说明': '数据核对与确认：约定推广效果数据的来源、统计口径、核对周期及双方确认程序。', '子条款列表': [], 'locator': '3.3'}, {'条款编号': '3.4', '条款大致说明': '结算周期与支付：约定结算周期（如按月/季度）、结算报表的出具与确认时限、乙方向甲方开具合规发票的要求、甲方支付分成款项的时限。', '子条款列表': [], 'locator': '3.4'}, {'条款编号': '3.5', '条款大致说明': '税务承担：约定因本协议产生的各项税费由双方依法各自承担。', '子条款列表': [], 'locator': '3.5'}], 'locator': '3'}, {'章节编号': '第四条', '章节标题': '双方权利与义务', '条款列表': [{'条款编号': '4.1', '条款大致说明': '甲方权利与义务：包括保证授权内容的合法性、按时提供授权素材、配合乙方必要的推广活动、按时结算费用等。', '子条款列表': [], 'locator': '4.1'}, {'条款编号': '4.2', '条款大致说明': '乙方权利与义务：包括在授权范围内使用授权内容、保证推广活动合法合规、维护甲方品牌形象、按时提供真实推广数据、配合甲方监督等。', '子条款列表': [], 'locator': '4.2'}], 'locator': '4'}, {'章节编号': '第五条', '章节标题': '知识产权', '条款列表': [{'条款编号': '5.1', '条款大致说明': '权利归属：明确授权内容的所有知识产权（包括但不限于著作权、商标权、肖像权等）归甲方所有，本协议不转让任何知识产权。', '子条款列表': [], 'locator': '5.1'}, {'条款编号': '5.2', '条款大致说明': '侵权责任条款：约定若因乙方使用授权内容的方式超出本协议范围或违法，导致侵犯第三方知识产权或引发任何纠纷、索赔，由乙方承担全部法律责任并赔偿甲方因此遭受的全部损失。', '子条款列表': [], 'locator': '5.2'}, {'条款编号': '5.3', '条款大致说明': '甲方维权：约定如发生第三方侵犯授权内容知识产权的情形，双方有义务相互通知并配合维权，相关权利行使主体及收益归属。', '子条款列表': [], 'locator': '5.3'}], 'locator': '5'}], '合同尾部': '（以下无正文）

